(() => {
'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=(x,d=0)=>new Intl.NumberFormat('tr-TR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(x);
const pct=x=>nf(x*100,3)+'%';
const statusNames={selected:'Seçildi',not_selected:'Kararlılık/katkı yetersiz',excluded_correlated:'Korelasyon temsilcisi var',excluded_missing:'Eksiklik yüksek',excluded_constant:'Sabit alan',excluded_dominance:'Baskın tek değer',review_cardinality:'Kategori incelemesi',missing_source:'Kaynakta yok',output_only:'Üretim çıktısı',review_role:'İş tanımı incelenecek',excluded_role:'Kapsam dışında',review_unmapped:'Sözlükte tanımsız',review_model_weak:'Model açıklayıcılığı incelenecek'};
function rows(data,state){return data.decisions.filter(r=>(state.selectionStatus==='all'||r.status===state.selectionStatus)&&(state.selectionFamily==='all'||r.family===state.selectionFamily)&&(!state.selectionSearch||(r.name+' '+r.label+' '+r.reason).toLocaleLowerCase('tr').includes(state.selectionSearch.toLocaleLowerCase('tr')))).sort((a,b)=>(b.status==='selected')-(a.status==='selected')||(b.mean_delta_wape??-1)-(a.mean_delta_wape??-1));}
function stabilityTable(data,selected){
 const windows=[...new Set(data.window_scores.map(r=>r.window))].sort();
 return `<section class="card space-bottom"><div class="card-head"><div><h2>Seçilen alanların dönem kararlılığı</h2><p>Her hücre ilgili dönemde göstergelerin eşit ağırlıklı ΔWAPE katkısıdır; değerler yüzde puandır.</p></div></div><div class="table-wrap selection-stability"><table class="data-table"><thead><tr><th>Seçilen alan</th>${windows.map(w=>`<th class="num">${esc(w)}</th>`).join('')}<th class="num">Pozitif dönem</th></tr></thead><tbody>${selected.map(r=>`<tr><td>${esc(r.label)}<span class="sub mono">${esc(r.name)}</span></td>${windows.map(w=>{const v=r.window_scores?.[w];return `<td class="num">${v==null?'—':`<span class="stability-value ${v>0?'positive':'nonpositive'}">${v>0?'+':''}${nf(v*100,3)}</span>`}</td>`;}).join('')}<td class="num">${r.positive_windows}/${r.windows}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function dictionaryTable(data){
 const config=data.selected_schema.config;
 const roles={candidate:'Kümeleme adayı',target:'Üretim çıktısı',context:'Bağlam',excluded:'Kapsam dışında',review:'İş incelemesi'};
 const types={numeric:'Sayısal',categorical:'Kategorik'};
 const grain={branch_month:'Hazır şube–ay',customer_month:'Müşteri–ay',customer_branch_month:'Müşteri–şube–ay'};
 return `<details class="card selection-details space-bottom"><summary>Alan sözlüğü: kaynak sütunları ve kullanım rolleri</summary><div class="card-body text-detail"><p>Veri düzeyi: <strong>${esc(grain[config.input.grain]||config.input.grain)}</strong>. ${nf(config.fields.length)} alan tanımı bulunur. Kimlik, dönem ve grup eşlemeleri açıklayıcı değişkenlerden ayrı tutulur.</p><p>Yeni sütunlar sözlüğe rol ve veri tipiyle eşlenir. Tanımsız alanlar otomatik modele alınmaz. Aşağıdaki sözlük bu çalışmada kullanılan tanımlardır.</p><a class="button secondary small" href="downloads/selection_dictionary.json" download>Bu sözlüğü indir</a></div><div class="table-wrap selection-dictionary"><table class="data-table"><thead><tr><th>Kaynak sütun</th><th>Modeldeki alan</th><th>Rol</th><th>Veri tipi</th><th>Toplulaştırma</th><th>Zamanında bilinirlik</th></tr></thead><tbody>${config.fields.map(f=>`<tr><td class="mono">${esc(f.source)}</td><td>${esc(f.label||f.name)}<span class="sub mono">${esc(f.name)}</span></td><td>${esc(roles[f.role]||f.role)}</td><td>${esc(types[f.dtype]||f.dtype)}</td><td>${esc(f.aggregation||(config.input.grain==='branch_month'?'Hazır şube düzeyi':'—'))}</td><td>${f.role==='candidate'?(f.known_by_period_end?(f.availability_lag_months?`${nf(f.availability_lag_months)} ay gecikmeli`:'İlgili ay sonunda biliniyor'):'İnceleme gerekli'):'—'}</td></tr>`).join('')}</tbody></table></div></details>`;
}
window.renderSelectionPage=(data,state)=>{
 if(!data)return '<section class="card"><div class="card-body">Doğrulanmış değişken seçimi çalışması yüklenmedi.</div></section>';
 const m=data.manifest,selected=data.decisions.filter(r=>r.status==='selected'),visible=rows(data,state);
 const top=[...selected].sort((a,b)=>b.mean_delta_wape-a.mean_delta_wape).slice(0,12);
 const max=Math.max(...top.map(r=>r.mean_delta_wape),.000001);
 const unknown=data.profile.filter(r=>r.status==='unmapped').length;
 const families=[...new Set(data.decisions.map(r=>r.family))].sort();
 const statuses=[...new Set(data.decisions.map(r=>r.status))].sort();
 const targets=Object.fromEntries(m.targets.map(t=>[t.name,t.label]));
 return `<div class="selection-page"><div class="selection-intro"><div><span class="badge model">Sözlükten çalışan seçim · CatBoost</span><h2>Kümeleme için ortak değişken seti</h2><p>Veri sonu ${esc(m.as_of)} · seçim etiketleri ${esc(m.selection_end)} ve öncesi. Alan adları ve sayıları sözlükten okunur.</p></div><a class="button secondary" href="downloads/selection_dictionary.json" download>Alan sözlüğünü indir</a></div><div class="kpi-grid">${[['Tanımlı aday',m.candidate_count,'İş rolü ve bilinirliği tanımlanmış'],['Kalite sonrası aday',m.eligible_count,'Eğitim verisinde kalite/korelasyon kontrolü'],['Seçilen ortak alan',m.selected_count,'Üç gösterge birlikte değerlendirilir'],['Tanımsız kaynak alanı',unknown,'Otomatik modele alınmaz']].map(([name,value,detail])=>`<div class="kpi"><div class="kpi-head">${name}</div><div class="kpi-value">${nf(value)}</div><small>${detail}</small></div>`).join('')}</div><section class="card space-bottom"><div class="card-body text-detail"><p><strong>Bu çalışma kümeleme girdisi hazırlar.</strong> CatBoost geçmiş üretim ilişkisini sınamak için kullanıldı; stok ekleyen tahmin modeli kullanılmadı. ${data.clustering_available?'Bu aday setiyle şube kümeleri oluşturuldu; sonuçlar Şube kümeleri ekranında. DEA ve hedef dağıtımı henüz yapılmadı.':'Bu seçim çalışması kümeleme girdisi üretir; DEA ve hedef dağıtımı içermez.'}</p><p>Kalite ve korelasyon kuralları en erken eğitim penceresinde belirlendi. Alanlar dönemler arası katkıyla seçildi; belirli bir alan sayısına zorlanmadı. Seçilen set, küme profilleri ve kararlılığıyla ayrıca değerlendirilecek.</p><p>Şema sürümü <code>${esc(m.run_id)}</code>. Yeni aday sürüm mevcut şemayı otomatik değiştirmez.</p><div class="selection-links"><a class="button secondary small" href="downloads/selection_schema.json" download>Seçilen şema</a><a class="button secondary small" href="downloads/selection_cluster_input_latest.csv" download>Son ay kümeleme girdisi</a><a class="button secondary small" href="downloads/selection_methodology.md" download>Metodoloji</a></div></div></section><section class="card space-bottom"><div class="card-head"><div><h2>Katkısı en yüksek seçilmiş alanlar</h2><p>Gösterge başına ΔWAPE, üç göstergeye eşit ağırlık · yüzde puan. Pozitif değer, alan karıştırılınca hatanın arttığını gösterir.</p></div></div><div class="card-body">${top.length?top.map(r=>`<div class="selection-bar"><span title="${esc(r.name)}">${esc(r.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,r.mean_delta_wape)/max*100}%;background:#318975"></div></div><strong>${nf(r.mean_delta_wape*100,3)} yp</strong></div>`).join(''):'<p>Otomatik seçilen alan yok; karar gerekçelerini inceleyin.</p>'}</div></section><section class="card space-bottom"><div class="card-head"><div><h2>Alan kararları ve gerekçeleri</h2><p>${nf(visible.length)} / ${nf(data.decisions.length)} kayıt · seçilmeyen alanlar ve üretim çıktıları da gösterilir.</p></div><button class="button secondary small" id="export-selection">Seçili tabloyu indir</button></div><div class="selection-controls"><label>Karar<select id="selection-status"><option value="all">Tüm kararlar</option>${statuses.map(s=>`<option value="${esc(s)}" ${state.selectionStatus===s?'selected':''}>${esc(statusNames[s]||s)}</option>`).join('')}</select></label><label>Alan ailesi<select id="selection-family"><option value="all">Tüm aileler</option>${families.map(s=>`<option value="${esc(s)}" ${state.selectionFamily===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Alan veya gerekçe ara<input id="selection-search" type="search" value="${esc(state.selectionSearch)}" placeholder="Değişken adı veya gerekçe"></label></div><div class="table-wrap selection-table"><table class="data-table"><thead><tr><th>Alan</th><th>Karar</th><th class="num">Ort. ΔWAPE · yp</th><th class="num">Pozitif dönem</th><th>Gerekçe</th></tr></thead><tbody>${visible.length?visible.map(r=>`<tr><td>${esc(r.label)}<span class="sub mono">${esc(r.name)}</span></td><td><span class="badge ${r.status==='selected'?'success':'planned'}">${esc(statusNames[r.status]||r.status)}</span></td><td class="num">${r.mean_delta_wape==null?'—':nf(r.mean_delta_wape*100,4)}</td><td class="num">${r.positive_windows==null?'—':r.positive_windows+'/'+r.windows}</td><td>${esc(r.reason)}${r.correlation!=null?`<span class="sub">Spearman: ${nf(r.correlation,3)}</span>`:''}</td></tr>`).join(''):'<tr><td colspan="5">Aramayla eşleşen alan yok.</td></tr>'}</tbody></table></div></section>${stabilityTable(data,selected)}${dictionaryTable(data)}<section class="card space-bottom"><div class="card-head"><div><h2>Seçim modellerinin dönem kontrolü</h2><p>Yalnızca aday yapısal alanlar kullanılır. Bu hatalar 49 alanlı stok tahmin deneyiyle aynı soruyu ölçmez.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Dönem</th><th>Gösterge</th><th>Eğitim etiketleri</th><th>Doğrulama etiketleri</th><th class="num">CatBoost WAPE</th><th class="num">Eğitim ortalaması</th><th>Katkı incelemesi</th></tr></thead><tbody>${data.metrics.map(r=>`<tr><td>${esc(r.window)}</td><td>${esc(targets[r.target]||r.target)}</td><td>${esc(r.train_start)} / ${esc(r.train_end)}</td><td>${esc(r.validation_start)} / ${esc(r.validation_end)}</td><td class="num">${pct(r.wape)}</td><td class="num">${pct(r.train_mean_wape)}</td><td>${r.informative?'Referanstan daha açıklayıcı':'İnceleme gerekli'}</td></tr>`).join('')}</tbody></table></div></section><details class="card selection-details space-bottom"><summary>Aylık şema uygulaması ve dağılım kontrolleri</summary><div class="card-body text-detail"><p>Kaydedilen şema aynı alan sırasını, eğitim medyanlarını ve kategori sözlüğünü korur. Yeni ay apply komutuyla yeniden eğitim olmadan hazırlanır. Zorunlu alan eksikse işlem durur; yeni alanlar raporlanır.</p><p>Önceki şemaya göre eklenen ${nf(data.comparison.added.length)}, çıkarılan ${nf(data.comparison.removed.length)} alan. ${data.comparison.baseline_run_id?'Önceki sürüm: '+esc(data.comparison.baseline_run_id):'Bu ilk sürüm; karşılaştırılacak önceki şema verilmedi.'}</p><a class="link-button" href="downloads/selection_drift.json" download>Dağılım kontrolünü indir</a></div></details><p class="inline-note">Finansallar ve bölgesel koşullar sentetiktir. Önemler nedensel potansiyel veya adil hedef dağıtımı kanıtı değildir. Son ${nf(m.holdout_months)} etiket ayı bu seçimde kullanılmadı; bu aylar önceki deneylerde görüldüğünden yeni el değmemiş test iddiası yoktur.</p></div>`;
};
window.exportSelectionTable=(data,state)=>{
 const columns=['name','label','family','dtype','status','mean_delta_wape','positive_windows','windows','reason'];
 const lines=[columns,...rows(data,state).map(r=>columns.map(c=>r[c]??''))];
 const csv='\ufeff'+lines.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n');
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='degisken_secimi_kararlari.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);
};
})();
